define(["jquery","core/modal_factory","core/modal_events","core/str"],function($,ModalFactory,ModalEvents,Str){
    "use strict";

    var selectors={
        form:'[data-region="modeussync-queue-form"]',
        item:'[data-region="queue-item"]',
        module:'[data-region="target-module"]',
        name:'[data-region="name-override"]',
        create:'[data-action="create"]',
        confirmation:'[data-region="confirm-recreate"]'
    };

    var isChanged=function(element){
        return element.value!==element.dataset.originalValue;
    };

    var changedTypeRows=function(form){
        return form.find(selectors.item).filter(function(index,row){
            var module=row.querySelector(selectors.module);
            return row.dataset.created==='1'&&isChanged(module);
        });
    };

    var updateCreateButton=function(form){
        var button=form.find(selectors.create);
        var changed=form.find(selectors.module+', '+selectors.name).toArray().some(isChanged);
        button.prop('disabled',!changed&&button.data('initial-disabled')===1);
    };

    var modalBody=function(rows,strings){
        var container=$('<div>');
        var list=$('<ul>');
        container.append($('<p>').text(strings[1]));
        rows.each(function(index,row){
            list.append($('<li>').text(row.dataset.itemName));
        });
        container.append(list);
        if(rows.toArray().some(function(row){return row.dataset.hasGrades==='1';})){
            container.append($('<p class="text-danger">').text(strings[3]));
        }
        return container.html();
    };

    var confirmRecreation=function(form,rows){
        return Str.get_strings([
            {key:'recreationconfirmationtitle',component:'mod_modeussync'},
            {key:'recreationconfirmationmessage',component:'mod_modeussync'},
            {key:'recreationconfirmationbutton',component:'mod_modeussync'},
            {key:'recreationgradedwarning',component:'mod_modeussync'}
        ]).then(function(strings){
            return ModalFactory.create({
                type:ModalFactory.types.SAVE_CANCEL,
                title:strings[0],
                body:modalBody(rows,strings)
            }).then(function(modal){
                var hasGrades=rows.toArray().some(function(row){return row.dataset.hasGrades==='1';});
                modal.setSaveButtonText(strings[2]);
                modal.getRoot().find('[data-action="save"]').prop('disabled',hasGrades);
                modal.getRoot().on(ModalEvents.save,function(event){
                    event.preventDefault();
                    form.find(selectors.confirmation).val('1');
                    form.append($('<input>',{type:'hidden',name:'action',value:'create'}));
                    form[0].submit();
                });
                modal.show();
                return modal;
            });
        });
    };

    return {init:function(){
        var form=$(selectors.form);
        var requestedAction=null;
        if(!form.length){
            return;
        }
        form.find('button[type="submit"]').on('click',function(event){
            requestedAction=event.currentTarget.value;
        });
        form.on('change input',selectors.module+', '+selectors.name,function(){
            updateCreateButton(form);
        });
        form.on('submit',function(event){
            var nativeEvent=event.originalEvent;
            var submitter=nativeEvent&&nativeEvent.submitter;
            var action=submitter?submitter.value:(requestedAction||'create');
            var rows;
            requestedAction=null;
            if(action!=='create'||form.find(selectors.confirmation).val()==='1'){
                if(!submitter&&action){
                    form.append($('<input>',{type:'hidden',name:'action',value:action}));
                }
                return;
            }
            rows=changedTypeRows(form);
            if(!rows.length){
                if(!submitter){
                    form.append($('<input>',{type:'hidden',name:'action',value:action}));
                }
                return;
            }
            event.preventDefault();
            confirmRecreation(form,rows);
        });
        updateCreateButton(form);
    }};
});
